/**
 * Copies the runtime bundle of the `/schemas` submodule (built by vite into
 * `dist/schemas`) next to the rolled-up type declarations (`schemas/index.d.ts`,
 * generated by api-extractor in `gen:docs`), so the published package exposes a
 * working runtime entry for `@empathyco/x-types/schemas`.
 *
 * The subpath is shipped as ESM only: its runtime registers the custom matchers
 * through `expect.extend`, which requires importing `vitest` — and vitest cannot
 * be `require()`d from a CommonJS module. Test files run under Vitest (ESM), so
 * an ESM bundle is the right target.
 *
 * Run automatically as part of `pnpm run build`.
 */
import { copyFileSync, existsSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import process from 'node:process'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const sourceDir = join(root, 'dist', 'schemas')
const targetDir = join(root, 'schemas')

if (!existsSync(sourceDir)) {
  console.error('[x-types] dist/schemas not found. Run "vite build" first.')
  process.exit(1)
}

mkdirSync(targetDir, { recursive: true })

const sourceEntry = join(sourceDir, 'index.es.js')
const sourceMap = join(sourceDir, 'index.es.js.map')
const targetEntry = join(targetDir, 'index.js')
const targetMap = join(targetDir, 'index.js.map')

for (const file of [sourceEntry, sourceMap]) {
  if (!existsSync(file)) {
    console.error(`[x-types] missing build output: ${file}`)
    process.exit(1)
  }
}

copyFileSync(sourceEntry, targetEntry)
copyFileSync(sourceMap, targetMap)

// Point the inline sourceMappingURL comment at the renamed map file.
const entry = readFileSync(targetEntry, 'utf8')
writeFileSync(
  targetEntry,
  entry.replace(/sourceMappingURL=index\.es\.js\.map/g, 'sourceMappingURL=index.js.map'),
)

console.log('[x-types] copied the /schemas runtime entry to schemas/')
